/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Parameter to include number of tasks.
/// </summary>
public class METVendCrossDocFeeService extends SysOperationServiceBase
{
    LedgerJournalTable      journalHeader;
    RecordInsertList        ledgerJournalTransList;
    str                     errorMessage;
    public str              infologMessage;

   

}

Method.Source:
    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Process the operation of the batch job and creates a header and line accordinly
    /// </summary>
    /// <param name = "_dataContract">object of data</param>
    public void processOperation(METVendCrossDocFeeContract _dataContract)
    {
        METVendCrossDocFees             metVendCrossDocFee;
        VendTrans                       vendtrans;
        boolean                         flag;
        LedgerJournalId                 journalId;
        LedgerJournalCheckPost          ledgerJournalCheckPost;
        

        flag = true;

        try
        {
            update_recordset    metVendCrossDocFee
                setting RecordStatus    = METRecordStatus::New,
                        ErrorMessage    = ''
                where metVendCrossDocFee.RecordStatus == METRecordStatus::Error;

            this.validateLines();

            while select metVendCrossDocFee
                join vendtrans
                    where vendtrans.Invoice == metVendCrossDocFee.Invoice  
                && metVendCrossDocFee.RecordStatus ==  METRecordStatus::New                    
            {
                if (flag)
                {
                    journalId = this.createJournalTable(_dataContract.getLedgerName(), metVendCrossDocFee.Description);
                    flag = false;
                }
                this.createJournalLines(journalId,
                                        _dataContract.getLedgerName(),
                                        metVendCrossDocFee);
                
            }

            if (journalHeader)
            {
                ledgerJournalTransList.insertDatabase();

                //Validating the journal
                ledgerJournalCheckPost = ledgerJournalCheckPost::newLedgerJournalTable(journalHeader, NoYes::Yes);
                if (ledgerJournalCheckPost.validate())
                {
                    //Posting the journal
                    ledgerJournalCheckPost.runOperation();
                }
            }
        }
        catch(Exception::CLRError)
        {
            //If an error occurs, check if log header is available
            this.getInfologMessage();
            System.Exception ex = CLRInterop::getLastException();
            errorMessage += ex.Message + ex.ToString();
            info(errorMessage + infologMessage);
            info ("@MET:VendCrossDocFeeErrorHandler");

        }
    }

    /// <summary>
    /// Validates vendor & tax information
    /// </summary>
    private void validateLines()
    {
        METVendCrossDocFees     metVendCrossDocFees;
        VendTable               vendTable;
        TaxGroupHeading         taxGroupHeading;
        TaxItemGroupHeading     taxItemGroupHeading;

        update_recordset metVendCrossDocFees
            setting RecordStatus = METRecordStatus::Error,
                    ErrorMessage = "@MET:InvalidVendor"
            notexists join vendTable
            where vendTable.AccountNum  == metVendCrossDocFees.AccountNum;

        update_recordset metVendCrossDocFees
            setting RecordStatus = METRecordStatus::Error,
                    ErrorMessage = metVendCrossDocFees.ErrorMessage + "@MET:InvalidSalesTaxGroup"
            notexists join taxGroupHeading
            where taxGroupHeading.TaxGroup == metVendCrossDocFees.SalesTaxGroup;

        update_recordset metVendCrossDocFees
            setting RecordStatus = METRecordStatus::Error,
                    ErrorMessage = metVendCrossDocFees.ErrorMessage + "@MET:InvalidSalesTaxItemGroup"
            notexists join taxItemGroupHeading
            where taxItemGroupHeading.TaxItemGroup  == metVendCrossDocFees.SalesTaxItemGroup;

    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// This method gets the info of the error into a variable
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;
        errorMessage    = '';
        infologMessage  = '';
        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());

            if (sysInfologEnumerator.currentException() == Exception::Error)
            {
                errorMessage += strfmt(sysInfologMessageStruct.message());
            }
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }

/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Returns a header
/// </summary>
/// <param name = "_ledgerJournalName">ledger jorunal name</param>
/// <param name = "_metVendCrossDocFeeDesc">metvendcrossdocfee table</param>
/// <returns>header</returns>
public LedgerJournalId createJournalTable(LedgerJournalNameId _ledgerJournalName, Name _metVendCrossDocFeeDesc)
{
    
    journalHeader.initValue();
    journalHeader.initFromLedgerJournalName(_ledgerJournalName);
    journalHeader.JournalNum =  JournalTableData::newTable(journalHeader).nextJournalId();
    journalHeader.Name = _metVendCrossDocFeeDesc;
    journalHeader.insert();
              
    return   journalHeader.JournalNum;
}

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// Creates lines for the header
    /// </summary>
    /// <param name = "_journalId">jorunal id</param>
    /// <param name = "_ledgerJournalName">ledger journal name</param>
    /// <param name = "_metVendCrossDocFees">Record of type METVendCrossDocFees</param>
    public void createJournalLines(LedgerJournalId _journalId, LedgerJournalNameId _ledgerJournalName, METVendCrossDocFees _metVendCrossDocFees)
    {
        LedgerJournalTrans      ledgerJournalTrans;
        NumberSeq               numberseq;
        Voucher                 voucherNum;
        str                     mainAccount = _metVendCrossDocFees.OffsetDefaultDimensionDisplayValue;

        LedgerJournalName   ledgerJournalName = LedgerJournalName::find(_ledgerJournalName);

        try
        {
            if(!ledgerJournalTransList)
            {
                ledgerJournalTransList = new RecordInsertList(ledgerJournalTrans.TableId);
            }

            numberseq = NumberSeq::newGetVoucherFromCode(NumberSequenceTable::find(ledgerJournalName.NumberSequenceTable).NumberSequence);
            voucherNum = numberseq.voucher();

            mainAccount = subStr(mainAccount, 1, strFind(mainAccount, '-', 1, strLen(mainAccount)));
            mainAccount = strRem(mainAccount, '-');
       
            ledgerJournalTrans.clear();
            ledgerJournalTrans.initValue();
            ledgerJournalTrans.JournalNum           =   _journalId;
            ledgerJournalTrans.TransDate            =   _metVendCrossDocFees.TransDate;
            ledgerJournalTrans.AccountType          =   LedgerJournalACType::Vend;
            ledgerJournalTrans.LedgerDimension      =   LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(_metVendCrossDocFees.AccountNum, LedgerJournalACType::Vend);
            ledgerJournalTrans.OffsetAccountType    =   LedgerJournalACType::Ledger;
            ledgerJournalTrans.Txt                  =   _metVendCrossDocFees.LineDescription;
            ledgerJournalTrans.OffsetTxt            =   _metVendCrossDocFees.LineDescription;
            ledgerJournalTrans.TaxGroup             =   _metVendCrossDocFees.SalesTaxGroup;
            ledgerJournalTrans.TaxItemGroup         =   _metVendCrossDocFees.SalesTaxItemGroup;
            ledgerJournalTrans.Invoice              =   _metVendCrossDocFees.Invoice + 'x';
            ledgerJournalTrans.DocumentDate         =   _metVendCrossDocFees.InvoiceDate;
  
            DimensionDynamicAccount ledgerAccount = LedgerDefaultAccountHelper::getDefaultAccountFromMainAccountRecId(MainAccount::findByMainAccountId(mainAccount).RecId);
            if(_metVendCrossDocFees.OffsetDefaultDimensionDisplayValue)
            {
                DefaultDimensionIntegrationValues ledgerString = _metVendCrossDocFees.OffsetDefaultDimensionDisplayValue;
                LedgerAccountDimensionResolver dimResolver = LedgerAccountDimensionResolver::newResolver(ledgerString);
                ledgerAccount = dimResolver.resolve();
            }

            ledgerJournalTrans.OffsetLedgerDimension = ledgerAccount;

            if (_metVendCrossDocFees.Balance > 0)
            {
                ledgerJournalTrans.AmountCurCredit    =   _metVendCrossDocFees.Balance;
            }
            else
            {
                ledgerJournalTrans.AmountCurDebit     =   _metVendCrossDocFees.Balance;
                ledgerJournalTrans.Payment            =   METVendTable::getCreditPaymId(_metVendCrossDocFees.AccountNum);
            }        

            ledgerJournalTrans.Approved               = NoYes::Yes;
            ledgerJournalTrans.Approver               = HcmWorker::userId2Worker(curuserid());
            ledgerJournalTrans.Voucher                = voucherNum;

            ledgerJournalTrans.SkipBlockedForManualEntryCheck  = true;
            ledgerJournalTrans.defaultRow();
            if (_metVendCrossDocFees.Balance != 0)
            {
                ledgerJournalTransList.add(ledgerJournalTrans);
            }

            numberseq.used();
            
            ttsbegin;
            _metVendCrossDocFees.selectForUpdate(true);
            _metVendCrossDocFees.RecordStatus = METRecordStatus::Processed;
            _metVendCrossDocFees.update();
            ttscommit;
        }
        catch
        {
            //If an error occurs, check if log header is available
            this.getInfologMessage();
            this.updateLogLine(errorMessage, infologMessage, _metVendCrossDocFees);

        }
    }

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// This method updates the error field in the table
    /// </summary>
    /// <param name = "_mbsErrorMsg">error message</param>
    /// <param name = "_mbsInfologMsg">info log</param>
    /// <param name = "_metVendCrossDocFee">METVendCrossDocFee table</param>
    private void updateLogLine(str _mbsErrorMsg, str _mbsInfologMsg, METVendCrossDocFees _metVendCrossDocFee)
    {
        ttsbegin;

        // if log header is available use the global variable to update the current log line to the below
        // status
        _metVendCrossDocFee.selectForUpdate(true);
        _metVendCrossDocFee.ErrorMessage = _mbsErrorMsg + _mbsInfologMsg;
        _metVendCrossDocFee.RecordStatus = METRecordStatus::Error;
        _metVendCrossDocFee.update();

        ttscommit;
    }
